do $$ declare pwd text; begin if exists(select 1 from vault.secrets where name in ('immojudis_licitor_db_password','immojudis_licitor_cron_secret')) then raise exception 'Licitor credentials already provisioned; refuse implicit rotation'; end if; pwd := encode(extensions.gen_random_bytes(32),'hex'); perform vault.create_secret(pwd,'immojudis_licitor_db_password','Dedicated Licitor acquisition login; private ingestion schema only'); perform vault.create_secret(encode(extensions.gen_random_bytes(32),'hex'),'immojudis_licitor_cron_secret','Dedicated Vercel collector trigger'); execute format('alter role licitor_collector login connection limit 4 password %L',pwd); end $$; alter role licitor_collector set statement_timeout='15s'; alter role licitor_collector set lock_timeout='3s';